<section class="patient-card patient-detail-section"><dl class="row mb-0"><?php foreach(['fecha'=>'Fecha','hora_inicio'=>'Hora inicial','hora_fin'=>'Hora final','paciente_nombre'=>'Paciente','medico_nombre'=>'Médico','especialidad_nombre'=>'Especialidad','estado'=>'Estado'] as $field=>$label): ?><div class="col-md-6 mb-3"><dt><?= $label ?></dt><dd><?= $escape($appointment[$field]) ?></dd></div><?php endforeach; ?></dl></section>
<?php if (\Clinica\Middleware\MedicalHistoryAccess::view($user) && isset($appointment['id_paciente'])): ?><div class="mt-3"><a class="btn btn-outline-primary" href="<?= $base === '/mis-citas' ? '/mis-citas/historial' : '/citas/historial-paciente' ?>?id=<?= $escape($appointment['id_paciente']) ?>">Historial del paciente</a></div><?php endif; ?>
<?php $notice=$_SESSION['cita_change_notice'] ?? $_SESSION['attendance_notice'] ?? null; if($notice && (int)$notice['id']===(int)$appointment['id_cita']): unset($_SESSION['cita_change_notice'],$_SESSION['attendance_notice']); ?><div class="alert alert-success mt-3" role="status"><?= $escape($notice['message']) ?></div><?php endif; ?>
