<?php if($version !== '' && $active && (\Clinica\Middleware\AttendanceAccess::control($user) || \Clinica\Middleware\AttendanceAccess::attend($user) || \Clinica\Middleware\AttendanceAccess::confirm($user))): ?>
<section class="patient-card mt-4"><h2 class="h5">Control de asistencia</h2><p class="text-secondary">Confirmar expresa intención de asistir; atendida solo indica que la consulta fue realizada.</p><div class="patient-form-actions">
<?php if(\Clinica\Middleware\AttendanceAccess::confirm($user)): ?><form method="post" action="/mis-citas/confirmar"><input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><input type="hidden" name="id" value="<?= $escape($appointment['id_cita']) ?>"><input type="hidden" name="version" value="<?= $escape($version) ?>"><button class="btn btn-outline-primary" <?= !\Clinica\Support\AttendanceFactory::enabled() ? 'disabled' : '' ?>>Confirmar asistencia</button></form><?php endif; ?>
<?php if(\Clinica\Middleware\AttendanceAccess::attend($user)): ?><form method="post" action="/citas/atender"><input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><input type="hidden" name="id" value="<?= $escape($appointment['id_cita']) ?>"><input type="hidden" name="version" value="<?= $escape($version) ?>"><button class="btn btn-clinic" <?= !\Clinica\Support\AttendanceFactory::enabled() ? 'disabled' : '' ?>>Marcar atendida</button></form><?php endif; ?>
<?php if(\Clinica\Middleware\AttendanceAccess::control($user)): ?><form method="post" action="/citas/asistencia"><input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><input type="hidden" name="id" value="<?= $escape($appointment['id_cita']) ?>"><input type="hidden" name="version" value="<?= $escape($version) ?>"><input type="hidden" name="accion" value="inasistencia"><button class="btn btn-outline-danger" <?= !\Clinica\Support\AttendanceFactory::enabled() ? 'disabled' : '' ?>>Registrar inasistencia</button></form><?php endif; ?>
</div><?php if(!\Clinica\Support\AttendanceFactory::enabled()): ?><div class="alert alert-info mt-3 mb-0">Las escrituras de asistencia están deshabilitadas; la cita no se modificará.</div><?php endif; ?></section>
<?php endif; ?>
<?php if($history): ?><section class="patient-card mt-4"><h2 class="h5">Historial de cambios de estado</h2><div class="table-responsive"><table class="table patient-table mb-0"><thead><tr><th>Fecha</th><th>Transición</th><th>Tipo</th><th>Actor</th></tr></thead><tbody><?php foreach($history as $change): ?><tr><td><?= $escape($change['fecha_hora_cambio']) ?></td><td><?= $escape(($change['estado_anterior'] ?? '—').' → '.($change['estado_nuevo'] ?? '—')) ?></td><td><?= $escape($change['tipo_cambio']) ?></td><td><?= $escape($change['nombre_usuario'] ?? 'Actor no registrado') ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<p class="text-secondary small mt-3">La llegada no tiene una columna independiente en el esquema actual; se conserva únicamente el estado de la cita y su historial.</p><a class="back-link text-start" href="<?= $escape($base) ?>">← Volver a citas</a>
<?php if(\Clinica\Middleware\BookingAccess::allowed($user) && $active && new DateTimeImmutable($appointment['fecha'].' '.$appointment['hora_inicio'],new DateTimeZone('America/La_Paz'))>new DateTimeImmutable('now',new DateTimeZone('America/La_Paz'))): ?><div class="patient-form-actions mt-4"><a class="btn btn-outline-primary" href="<?= $escape($base) ?>/reprogramar?id=<?= $escape($appointment['id_cita']) ?>">Reprogramar</a><a class="btn btn-outline-danger" href="<?= $escape($base) ?>/cancelar?id=<?= $escape($appointment['id_cita']) ?>">Cancelar cita</a></div><?php endif; ?>
